class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        if root is None:
            return None
        if root.val == p.val or root.val == q.val:
            return root
        left = self.lowestCommonAncestor(root.left, p, q)
        right = self.lowestCommonAncestor(root.right, p, q)
        if left is not None and right is not None:
            return root
        if left is None:
            return right
        return left

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        parent, visited = {}, set()

        def dfs(r: 'TreeNode') -> None:
            if r is None:
                return
            if r.left is not None:
                parent[r.left.val] = r
                dfs(r.left)
            if r.right is not None:
                parent[r.right.val] = r
                dfs(r.right)

        dfs(root)
        while p is not None:
            visited.add(p.val)
            p = parent.get(p.val)
        while q is not None:
            if q.val in visited:
                return q
            q = parent.get(q.val)
        return None
